class Solution { public boolean validSquare(int[] p1,int[] p2,int[] p3,int[] p4){int[][] points={p1,p2,p3,p4};long[] distances=new long[6];int index=0;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)distances[index++]=distance(points[i],points[j]);Arrays.sort(distances);return distances[0]>0&&distances[0]==distances[3]&&distances[4]==distances[5]&&distances[4]==2*distances[0];}private long distance(int[] a,int[] b){long x=(long)a[0]-b[0],y=(long)a[1]-b[1];return x*x+y*y;} }
